-- ---------- 习题：C 语言（66-70，每题 3 道） ----------
INSERT INTO question (knowledge_id, source, difficulty, type, title, options, answer, analysis, score) VALUES

-- ---------- 66 指针与地址运算 ----------
(66,'考研408',3,'single','读程序写结果：\n#include <stdio.h>\nint main(void) {\n    int a[5] = {1, 2, 3, 4, 5};\n    int *p = a;\n    p += 2;\n    printf("%d %d", *p, (int)(p - a));\n    return 0;\n}\n程序的输出是？',
 '[{"key":"A","text":"3 2"},{"key":"B","text":"2 3"},{"key":"C","text":"3 8"},{"key":"D","text":"2 8"}]',
 'A','p 初值为 a 即 &a[0]，p += 2 前进两个 int 指向 a[2]，故 *p 为 3；两个同类型指针相减得到的是相隔的元素个数 2，而不是字节数 8，故 C、D 错；B 把值与距离写反了。',5),
(66,'期末',2,'judge','判断下列说法是否正确：数组名 a 代表数组首元素的地址，它是一个地址常量，因此 a++ 或 a = p 这样的写法都是非法的。',
 '[]','T','正确。数组名在表达式中退化为首元素地址，但它不是指针变量，而是不可修改的地址常量，不能自增也不能被赋值；需要对数组做指针算术时应另建 int *p = a 再操作 p。',3),
(66,'软考',3,'single','已有定义 int x = 3; int *p = &x;，则表达式 *p++ 的效果是？',
 '[{"key":"A","text":"值为 3，求值结束后 p 指向 x 之后的下一个 int 位置"},{"key":"B","text":"值为 3，求值结束后 x 自增为 4"},{"key":"C","text":"值为 x 的地址，求值结束后 p 自增"},{"key":"D","text":"先让 x 自增再解引用，结果为 4"}]',
 'A','后置 ++ 优先级高于 *，故 *p++ 等价于 *(p++)：先取 p 当前所指的值 3 作为表达式结果，再把 p 向后移动一个 int。B、D 描述的是 (*p)++；C 把取值误认为取地址。',5),

-- ---------- 67 函数调用与栈帧 ----------
(67,'期末',2,'single','读程序写结果：\n#include <stdio.h>\nvoid f(int a, int *b) { a = a + 1; *b = *b + 1; }\nint main(void) {\n    int x = 1, y = 1;\n    f(x, &y);\n    printf("%d %d", x, y);\n    return 0;\n}\n程序的输出是？',
 '[{"key":"A","text":"1 1"},{"key":"B","text":"1 2"},{"key":"C","text":"2 1"},{"key":"D","text":"2 2"}]',
 'B','C 语言只有值传递：形参 a 是 x 的副本，a+1 不影响 x，故 x 仍为 1；形参 b 拷贝的是 y 的地址，*b = *b + 1 通过地址间接改写了 main 中的 y，故 y 为 2。',5),
(67,'软考',2,'judge','判断下列说法是否正确：递归调用层数过多会耗尽调用栈空间，导致栈溢出（stack overflow），因此递归必须设置明确的出口条件。',
 '[]','T','正确。每次递归调用都会在调用栈上新建一个栈帧保存参数、返回地址与局部变量，没有出口或深度过大时栈空间被耗尽。尾部递归可改写为迭代以节省栈开销。',3),
(67,'考研408',3,'single','读程序写结果：\n#include <stdio.h>\nint f(void) { static int c = 0; c = c + 1; return c; }\nint main(void) {\n    int a = f(), b = f(), d = f();\n    printf("%d %d %d", a, b, d);\n    return 0;\n}\n程序的输出是？',
 '[{"key":"A","text":"1 1 1"},{"key":"B","text":"1 2 3"},{"key":"C","text":"3 3 3"},{"key":"D","text":"0 1 2"}]',
 'B','static 局部变量在静态存储区而非栈帧，只初始化一次、函数返回后保留，故三次调用返回 1、2、3。A 忽略其保持性；D 以为每次从 0 重新计数。',5),

-- ---------- 68 结构体与内存对齐 ----------
(68,'软考',3,'single','假设 int 占 4 字节、按 4 字节对齐，则 struct S { char a; int b; char c; }; 的 sizeof(struct S) 为？',
 '[{"key":"A","text":"6"},{"key":"B","text":"8"},{"key":"C","text":"10"},{"key":"D","text":"12"}]',
 'D','a 在偏移 0，b 需对齐到 4 故偏移为 4（中间填充 3 字节），c 在偏移 8，最后整体大小需补齐为最大对齐数 4 的倍数，故为 12。A 是没有对齐时的理论值；B、C 未按 4 的倍数补齐。',5),
(68,'期末',2,'judge','判断下列说法是否正确：结构体成员的声明顺序会影响 sizeof 的结果，把对齐要求相同的成员放在一起通常可以减少填充字节。',
 '[]','T','正确。例如 {char,int,char} 为 12 字节，而 {int,char,char} 只需 8 字节，因为两个 char 可以紧邻存放，仅末尾补 2 字节。这是结构体优化的常用手段。',3),
(68,'NCRE',2,'single','读程序写结果：\n#include <stdio.h>\nstruct P { int x; };\nint main(void) {\n    struct P a = {1}, b;\n    b = a;\n    b.x = 9;\n    printf("%d %d", a.x, b.x);\n    return 0;\n}\n程序的输出是？',
 '[{"key":"A","text":"1 9"},{"key":"B","text":"9 9"},{"key":"C","text":"1 1"},{"key":"D","text":"9 1"}]',
 'A','结构体可以用 = 整体赋值，编译器按字节拷贝生成一个独立副本，之后修改 b.x 不会影响 a，故输出 1 9。B 误以为赋值后两个名字共享同一对象（那是结构体指针的情况）。',5),

-- ---------- 69 数组、字符串与越界 ----------
(69,'NCRE',2,'single','已有定义 char s[] = "abc";，则 sizeof(s) 与 strlen(s) 的值分别是？',
 '[{"key":"A","text":"3 和 3"},{"key":"B","text":"4 和 3"},{"key":"C","text":"3 和 4"},{"key":"D","text":"4 和 4"}]',
 'B','字符串字面量末尾由编译器自动补一个结束符，数组长度为 4，故 sizeof 为 4；strlen 只统计结束符之前的字符个数，故为 3。C、D 把 strlen 的结果也算上了结束符。',5),
(69,'期末',1,'judge','判断下列说法是否正确：C 编译器会在编译阶段检查数组下标是否越界，凡是越界的访问都会产生编译错误。',
 '[]','F','错误。C 语言不对数组下标做边界检查，越界访问属于未定义行为：可能读到脏数据、破坏相邻变量、破坏栈帧，也可能暂时看起来正常，这正是 C 程序调试困难的原因之一。',3),
(69,'考研408',3,'single','读程序写结果：\n#include <stdio.h>\n#include <string.h>\nint main(void) {\n    char s[] = "hello";\n    s[2] = 0;\n    printf("%s %zu", s, strlen(s));\n    return 0;\n}\n程序的输出是？',
 '[{"key":"A","text":"he 2"},{"key":"B","text":"he 5"},{"key":"C","text":"hello 5"},{"key":"D","text":"hello 2"}]',
 'A','把下标 2 改成结束符后字符串在此截断，%s 只输出 he，strlen 同样只统计到第一个结束符之前，故为 2；后面的字符仍留在数组中但已不属于字符串，所以 B、C、D 都不对。',5),

-- ---------- 70 动态内存 malloc/free ----------
(70,'软考',3,'single','下列关于 malloc 与 free 的说法，正确的是？',
 '[{"key":"A","text":"malloc(0) 一定返回 NULL"},{"key":"B","text":"对同一块动态内存重复 free 属于未定义行为，可能破坏堆管理结构"},{"key":"C","text":"free(p) 之后 p 会自动变成 NULL"},{"key":"D","text":"malloc 申请的空间在栈区，函数返回后自动回收"}]',
 'B','重复 free 同一块堆内存会破坏堆管理结构，属未定义行为，应 free 后立即置空。A 错在 malloc(0) 由实现决定；C 错在 free 不改指针变量本身；D 错在堆内存不会自动回收。',5),
(70,'期末',2,'judge','判断下列说法是否正确：用 malloc 申请的内存如果一直没有 free，程序运行期间这块内存会持续被占用，多次发生就会造成内存泄漏。',
 '[]','T','正确。堆内存由程序员手动管理，不再使用又不释放时，程序本身也失去了这块内存的引用，无法再回收，长时间运行的服务进程会因此耗尽可用内存。',3),
(70,'考研408',3,'single','读程序写结果：\n#include <stdio.h>\n#include <stdlib.h>\nint main(void) {\n    int *p = (int *)malloc(3 * sizeof(int));\n    p[0] = 1; p[1] = 2; p[2] = 3;\n    int *q = p + 1;\n    printf("%d %d", *q, q[-1]);\n    free(p);\n    return 0;\n}\n程序的输出是？',
 '[{"key":"A","text":"2 1"},{"key":"B","text":"1 2"},{"key":"C","text":"2 2"},{"key":"D","text":"运行崩溃"}]',
 'A','q 指向 p[1]，故 *q 为 2；下标允许为负，q[-1] 等价于 *(q - 1) 即 p[0]，值为 1。动态申请的空间同样支持指针算术，访问发生在 free 之前，完全合法，故 D 不成立。',5);

