-- ============================================================
INSERT INTO knowledge (id, course_id, name, summary, content, route, sort_no, difficulty, tags) VALUES

(71,11,'类、构造与析构','类把数据与操作封装在一起；构造函数负责初始化、析构函数负责释放资源，含指针成员时必须自己实现深拷贝构造。',
'## 核心概念\n类（class）是**数据与操作的封装单元**，`class` 的成员默认 private，`struct` 默认 public。三个关键成员函数决定了对象的生老病死：\n\n1. **构造函数**：与类同名、没有返回类型，对象创建时自动调用，负责把对象置为合法状态。推荐使用**成员初始化列表** `: x_(x), y_(y)`，它比在函数体中赋值少一次默认构造。\n2. **析构函数**：`~类名()`、无参无返回值，对象销毁时自动调用，负责释放资源（delete、close 等）。\n3. **拷贝构造函数**：用同类型的已有对象初始化新对象，形如 `T(const T&)`。编译器默认给出的是**逐成员浅拷贝**，若类里有指针成员，两个对象会指向同一块内存，析构时发生**双重释放**。\n\n对象的生命周期遵循：局部对象在离开作用域时析构，且**析构顺序与构造顺序相反**；`new` 出来的对象必须 `delete` 才会析构。\n\n## 代码示例\n\n示例一：构造、析构与调用时机。\n\n```cpp\n#include <iostream>\nusing namespace std;\nclass Point {\n    int x_, y_;                       // 默认 private，外部无法直接访问\npublic:\n    Point(int x = 0, int y = 0) : x_(x), y_(y) {   // 成员初始化列表\n        cout << "ctor (" << x_ << "," << y_ << ")\\n";\n    }\n    ~Point() { cout << "dtor (" << x_ << "," << y_ << ")\\n"; }  // 对象销毁时调用\n    int sum() const { return x_ + y_; }            // const 成员函数不修改对象\n};\nint main() {\n    Point a(1, 2);                    // 构造，输出 ctor (1,2)\n    cout << a.sum() << endl;          // 输出 3\n    { Point b(3, 4); }                // 进入块构造，离开块立即析构\n    return 0;\n}                                     // main 结束，a 析构\n```\n\n示例二：含指针成员时必须写深拷贝构造。\n\n```cpp\n#include <iostream>\nusing namespace std;\nclass Buffer {\n    int *data_; int n_;\npublic:\n    explicit Buffer(int n) : data_(new int[n]), n_(n) {}   // 构造时申请资源\n    Buffer(const Buffer &o) : data_(new int[o.n_]), n_(o.n_) {  // 深拷贝：另开空间\n        for (int i = 0; i < n_; ++i) data_[i] = o.data_[i];\n    }\n    ~Buffer() { delete[] data_; }                          // 析构时释放资源\n    int size() const { return n_; }\n};\nint main() {\n    Buffer a(4);\n    Buffer b = a;                     // 调用拷贝构造，若用默认版本会双重释放\n    cout << a.size() << " " << b.size() << endl;           // 输出 4 4\n    return 0;\n}\n```\n\n## 易错点\n1. 现象：含指针成员的类直接赋值或拷贝后程序崩溃。→ 原因：默认拷贝是浅拷贝，两个对象共享同一块内存。→ 正确写法：实现深拷贝的拷贝构造与赋值运算符（Rule of Three）。\n2. 现象：写了带参数的构造函数后 `T t;` 编译失败。→ 原因：显式定义构造函数后编译器不再合成默认构造。→ 正确写法：再写一个默认构造，或给所有参数加默认值。\n3. 现象：在构造函数体内给成员赋值，const 成员或引用成员报错。→ 原因：它们只能在初始化列表中初始化。→ 正确写法：改用 `: m_(v)` 形式的成员初始化列表。\n4. 现象：`new` 出来的对象析构函数从未被调用。→ 原因：忘记 `delete`。→ 正确写法：配对使用 new/delete、new[]/delete[]，或用智能指针。\n5. 现象：形参传对象时开销大且产生多余拷贝。→ 原因：值传递触发拷贝构造。→ 正确写法：用 `const T&` 常量引用传参。\n\n## 考点提示\n1. 读程序写结果：构造/析构的调用顺序（先构造的后析构）。\n2. 拷贝构造被调用的三种场景：用对象初始化对象、值传参、值返回。\n3. 深拷贝与浅拷贝的辨析，以及 Rule of Three（析构、拷贝构造、赋值运算符）。\n4. `explicit` 关键字阻止隐式类型转换的作用。\n5. 面试：成员初始化列表相对于赋值的优势；对象作为函数返回值的拷贝省略（RVO）。',
'/code/cpp-class',1,3,'类,构造函数,析构函数,拷贝构造,深拷贝'),

(72,11,'虚函数与运行时多态','virtual 成员函数通过虚表在运行期按对象实际类型分派；基类指针删除派生类对象时，基类析构函数必须是虚函数。',
'## 核心概念\n**多态**指同一条调用语句在不同对象上表现出不同行为。C++ 分两种绑定：\n\n- **静态绑定（编译期）**：普通成员函数按指针/引用的**声明类型**决定调用哪个版本；\n- **动态绑定（运行期）**：`virtual` 成员函数按对象的**实际类型**分派。\n\n实现原理：含虚函数的对象内部有一个**虚表指针 vptr**，指向类的虚函数表 vtable；调用虚函数时先通过 vptr 找到 vtable，再取出函数地址。因此虚函数有一次间接寻址的开销，且**构造函数不能是虚函数**（构造期间 vptr 尚未建立完成）。\n\n三条实践规则：\n\n1. 派生类重写时加 `override`，让编译器帮你检查签名是否一致；\n2. 作为基类的类，析构函数应声明为 `virtual`；\n3. 通过**基类指针或引用**调用虚函数才会触发多态，用对象名直接调用不会。\n\n## 代码示例\n\n示例一：虚函数实现运行时多态。\n\n```cpp\n#include <iostream>\nusing namespace std;\nclass Animal {\npublic:\n    virtual void speak() const { cout << "...\\n"; }   // virtual 允许派生类重写\n    virtual ~Animal() {}                              // 基类析构应为虚函数\n};\nclass Dog : public Animal {\npublic:\n    void speak() const override { cout << "wang\\n"; } // override 确保签名匹配\n};\nclass Cat : public Animal {\npublic:\n    void speak() const override { cout << "miao\\n"; }\n};\nint main() {\n    Dog d; Cat c;\n    Animal *p1 = &d;              // 基类指针指向派生类对象\n    Animal *p2 = &c;\n    p1->speak();                  // 运行期按实际对象调用，输出 wang\n    p2->speak();                  // 输出 miao\n    return 0;\n}\n```\n\n示例二：虚析构保证派生部分被正确释放。\n\n```cpp\n#include <iostream>\nusing namespace std;\nclass Base {\npublic:\n    virtual ~Base() { cout << "~Base\\n"; }        // 虚析构\n};\nclass Derived : public Base {\n    int *buf_;\npublic:\n    Derived() : buf_(new int[4]) {}               // 派生类持有资源\n    ~Derived() override { delete[] buf_; cout << "~Derived\\n"; }\n};\nint main() {\n    Base *p = new Derived();   // 基类指针指向派生类对象\n    delete p;                  // 析构为虚，先 ~Derived 再 ~Base\n    return 0;\n}\n```\n\n## 易错点\n1. 现象：通过基类指针 delete 派生类对象，派生类的资源没释放。→ 原因：基类析构非虚，`delete` 只调用基类版本。→ 正确写法：把基类析构函数声明为 `virtual`。\n2. 现象：派生类函数写了 `override` 却编译报错。→ 原因：签名与基类虚函数不一致（漏了 const、参数类型不同）。→ 正确写法：对照基类声明修正签名，或去掉 override 表示这是新函数。\n3. 现象：用对象（而非指针/引用）调用虚函数，调用的仍是基类版本。→ 原因：对象静态类型已知，编译期即可确定，不查虚表。→ 正确写法：通过基类指针或引用调用。\n4. 现象：在构造函数中调用虚函数，得到的却是基类版本。→ 原因：构造基类子对象时派生部分还不存在。→ 正确写法：避免在构造/析构中调用虚函数。\n5. 现象：忘记给虚函数加 `virtual`，多态失效。→ 原因：只有基类中声明为 virtual 的函数才进入虚表。→ 正确写法：基类加 virtual，派生类可省略但建议加 override。\n\n## 考点提示\n1. 读程序写结果：虚函数与非虚函数混用时判断输出（期末、面试高频）。\n2. 纯虚函数与抽象类：`virtual f() = 0;` 使类成为抽象类，不能实例化。\n3. 虚析构的作用与必要性（软考、面试必问）。\n4. 虚表、虚表指针的内存开销，以及一个类只增加 sizeof(指针) 的事实。\n5. 重载、重写（覆盖）、隐藏三者的区别。',
'/code/cpp-polymorphism',2,4,'虚函数,多态,虚表,override,虚析构'),

(73,11,'模板与泛型编程','模板把类型作为参数，在编译期实例化出具体版本的代码；函数模板自动推导类型，类模板还可带非类型参数。',
'## 核心概念\n模板是 C++ **泛型编程**的基础，它把「类型」也变成参数，从而一份代码服务多种类型。\n\n- **函数模板**：`template <typename T> T add(T a, T b)`。调用时编译器根据实参**推导** T，也可以显式指定 `add<int>(1, 2)`。\n- **类模板**：`template <typename T, int N> class Array`，参数可以是类型，也可以是**非类型参数**（必须是编译期常量，如整型、指针、引用）。\n- **实例化**：模板本身不生成代码，只在使用时于**编译期**生成对应类型的版本，所以模板定义通常要放在**头文件**里，否则链接时找不到符号。\n\n模板的代价是：编译时间变长、错误信息难读、代码体积膨胀。它的优势是**零运行时开销**（没有装箱、没有虚调用），这也是 STL 高性能的来源。\n\n## 代码示例\n\n示例一：函数模板与类型推导。\n\n```cpp\n#include <iostream>\n#include <string>\nusing namespace std;\ntemplate <typename T>\nT max2(T a, T b) {                      // 函数模板，编译期按实参生成版本\n    return a > b ? a : b;\n}\nint main() {\n    cout << max2(3, 5) << endl;              // T 推导为 int，输出 5\n    cout << max2(2.5, 1.5) << endl;          // T 推导为 double，输出 2.5\n    cout << max2<string>("ab", "b") << endl; // 显式指定 T，输出 b\n    return 0;\n}\n```\n\n示例二：类模板与非类型模板参数。\n\n```cpp\n#include <iostream>\nusing namespace std;\ntemplate <typename T, int N>\nclass Array {                           // N 必须是编译期常量\n    T data_[N];\npublic:\n    int size() const { return N; }\n    T &operator[](int i) { return data_[i]; }  // 返回引用，可被赋值\n};\nint main() {\n    Array<int, 3> a;\n    a[0] = 10; a[1] = 20; a[2] = 30;\n    cout << a.size() << " " << a[1] << endl;   // 输出 3 20\n    return 0;\n}\n```\n\n## 易错点\n1. 现象：`max2(1, 2.5)` 编译失败。→ 原因：两个实参推导出的 T 不一致且无法转换。→ 正确写法：显式指定 `max2<double>(1, 2.5)`，或用两个模板参数 `template <typename T, typename U>`。\n2. 现象：模板定义放在 .cpp 中，链接时报错 undefined reference。→ 原因：实例化时看不到定义。→ 正确写法：模板声明与定义都写在头文件（或使用显式实例化）。\n3. 现象：`Array<int, n> a;` 编译失败。→ 原因：非类型参数必须是编译期常量，变量 n 不行。→ 正确写法：改用 `constexpr int n = 3;` 或直接用字面量。\n4. 现象：模板中对类型 T 调用了不存在的操作，报错信息极长。→ 原因：模板在使用时才检查。→ 正确写法：用 `static_assert` 或 C++20 的 concept 给出约束与清晰报错。\n5. 现象：嵌套模板写成 `vector<vector<int>>` 在老编译器上报错。→ 原因：`>>` 被解析为右移运算符。→ 正确写法：C++11 起已支持，老标准需写成 `> >`。\n\n## 考点提示\n1. 模板实例化的时机是**编译期**而非运行期（选择题常设陷阱）。\n2. 函数模板与普通函数重载时的匹配优先级：普通函数优先。\n3. 类模板的成员函数只有在被使用时才实例化。\n4. 模板特化（全特化、偏特化）的写法与用途。\n5. 面试：vector<bool> 的特化问题；模板导致的二阶段查找（two-phase lookup）。',
'/code/cpp-template',3,4,'模板,泛型,函数模板,类模板,实例化'),

(74,11,'STL 容器与迭代器','vector、map 等容器配合迭代器使用；vector 扩容会使迭代器全部失效，map 插入删除不影响其它元素的迭代器。',
'## 核心概念\nSTL 由**容器、迭代器、算法**三部分组成，迭代器是把容器与算法解耦的「泛型指针」。\n\n常用容器对比：\n\n| 容器 | 底层结构 | 特点 |\n|---|---|---|\n| vector | 连续数组 | 随机访问 O(1)，尾部插入均摊 O(1) |\n| list | 双向链表 | 任意位置插入删除 O(1)，不支持随机访问 |\n| deque | 分段连续 | 头尾插入都高效 |\n| map / set | 红黑树 | 有序，增删查 O(log n) |\n| unordered_map | 哈希表 | 无序，平均 O(1) |\n\n**迭代器失效**是使用容器最隐蔽的坑：`vector` 在 `push_back` 触发扩容时会重新分配内存，此前获得的所有迭代器、引用、指针全部失效；`erase` 会使被删元素及其之后的迭代器失效（应接收返回值 `it = v.erase(it)`）；而 `map`/`set` 是节点式容器，插入不会使任何迭代器失效，删除只使指向被删元素的迭代器失效。\n\n## 代码示例\n\n示例一：vector 与迭代器遍历。\n\n```cpp\n#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    vector<int> v = {1, 2, 3};            // 动态数组，尾插均摊 O(1)\n    v.push_back(4);                       // 尾部插入\n    cout << v.size() << endl;             // 输出 4\n    for (vector<int>::iterator it = v.begin(); it != v.end(); ++it)\n        cout << *it << " ";               // 迭代器像指针一样解引用\n    cout << endl;                         // 输出 1 2 3 4\n    cout << v.front() << " " << v.back() << endl;  // 输出 1 4\n    return 0;\n}\n```\n\n示例二：map 的有序性与迭代器失效。\n\n```cpp\n#include <iostream>\n#include <map>\n#include <vector>\n#include <string>\nusing namespace std;\nint main() {\n    map<string, int> m;                   // 红黑树，按键有序，查找 O(log n)\n    m["apple"] = 3;                       // operator[] 不存在时插入默认值\n    m["banana"] = 5;\n    m["apple"] += 1;                      // 同键覆盖，apple 变为 4\n    cout << m["apple"] << " " << m.size() << endl;  // 输出 4 2\n    vector<int> v = {1, 2, 3};\n    auto it = v.begin();\n    v.push_back(4);                       // 可能扩容，原有迭代器全部失效\n    it = v.begin();                       // 失效后必须重新获取\n    cout << *it << endl;                  // 输出 1\n    return 0;\n}\n```\n\n## 易错点\n1. 现象：循环中 `v.push_back` 后继续使用旧迭代器，结果错乱甚至崩溃。→ 原因：扩容使迭代器失效。→ 正确写法：先用 `reserve` 预留容量，或插入后重新获取迭代器。\n2. 现象：用 `for (auto x : v) v.erase(...)` 遍历时删除元素导致崩溃。→ 原因：范围 for 内部是迭代器，删除会使其失效。→ 正确写法：用 `it = v.erase(it)` 接收返回值继续遍历。\n3. 现象：`map[key]` 访问不存在的键后 map 变大了。→ 原因：operator[] 会**插入**默认值。→ 正确写法：只查询时用 `m.find(key)` 或 `m.count(key)`。\n4. 现象：对自定义类型使用 map/set 编译报错。→ 原因：未提供 `operator<` 或比较器。→ 正确写法：定义严格弱序的比较函数。\n5. 现象：遍历 unordered_map 的输出顺序与插入顺序不同。→ 原因：哈希表按桶存储，不保证顺序。→ 正确写法：需要有序就用 map，或取出后自行排序。\n\n## 考点提示\n1. vector 与 list / deque 的复杂度对比与选型（软考高频）。\n2. 迭代器失效的三种典型场景（vector 扩容、erase、map 删除）。\n3. `size()`、`capacity()`、`reserve()`、`resize()` 的区别。\n4. 常用算法 `sort`、`find`、`count` 与 `[begin, end)` 左闭右开区间。\n5. 面试：vector 扩容策略（通常 1.5 或 2 倍）；map 与 unordered_map 的取舍。',
'/code/cpp-stl',4,3,'STL,vector,map,迭代器,迭代器失效'),

(75,11,'引用、移动语义与 RAII','引用是对象的别名且必须初始化；RAII 把资源生命周期绑定到对象作用域，移动语义让资源所有权以 O(1) 代价转移。',
'## 核心概念\n**引用**是已有对象的别名：`int &r = a;` 之后对 r 的一切操作都作用在 a 上。与指针对比：引用必须在定义时初始化、不能改绑、不能为「空」，也没有独立的存储空间（sizeof 得到的是被引对象的大小）。函数形参用 `const T&` 可以同时避免拷贝和保护实参。\n\n**RAII（Resource Acquisition Is Initialization）** 是 C++ 最重要的资源管理思想：把资源的获取放在构造函数、释放放在析构函数，利用「离开作用域自动析构」保证资源一定被释放，即使中途抛异常也不会泄漏（智能指针、锁、文件句柄都基于它）。\n\n**移动语义**（C++11）解决不必要的深拷贝：\n\n- 左值是有名字、可取地址的对象；右值是临时对象；\n- `T&&` 是右值引用，`std::move(x)` 把左值**转换**为右值引用（本身不移动任何东西）；\n- 移动构造只**转移指针所有权**，代价 O(1)，移动后源对象处于「有效但未指定」状态。\n\n## 代码示例\n\n示例一：引用是别名，值传递只是副本。\n\n```cpp\n#include <iostream>\nusing namespace std;\nvoid inc(int &r) { r += 1; }          // 引用形参：改 r 就是改实参\nint main() {\n    int a = 5;\n    int &r = a;                       // 引用必须在定义时初始化，之后不可改绑\n    inc(r);                           // a 变为 6\n    cout << a << " " << r << endl;    // 输出 6 6\n    int b = a;                        // 普通拷贝，b 是独立变量\n    b = 100;\n    cout << a << " " << b << endl;    // 输出 6 100\n    return 0;\n}\n```\n\n示例二：移动语义与 RAII。\n\n```cpp\n#include <iostream>\n#include <vector>\n#include <utility>\nusing namespace std;\nclass Holder {                        // RAII：构造获取资源，析构自动释放\n    int *p_;\npublic:\n    explicit Holder(int n) : p_(new int[n]) { cout << "acquire\\n"; }\n    ~Holder() { delete[] p_; cout << "release\\n"; }\n    Holder(const Holder &) = delete;  // 禁止拷贝，避免双重释放\n    Holder(Holder &&o) noexcept : p_(o.p_) { o.p_ = nullptr; } // 移动：转移所有权\n};\nint main() {\n    vector<int> a = {1, 2, 3};\n    vector<int> b = std::move(a);     // 移动构造，O(1) 接管内部缓冲区\n    cout << "b=" << b.size() << "\\n";  // 输出 b=3，此后不应再使用 a 的内容\n    Holder h(8);                      // 输出 acquire\n    {\n        Holder h2 = std::move(h);     // 资源转移给 h2，h.p_ 被置空\n    }                                 // h2 离开作用域，输出 release\n    cout << "done\\n";\n    return 0;\n}                                     // h 析构，delete[] nullptr 安全，输出 release\n```\n\n## 易错点\n1. 现象：以为 `T&&` 参数里传进来的对象还能正常使用。→ 原因：移动后源对象处于有效但未指定状态。→ 正确写法：移动后不要再读取源对象，需要时重新赋值。\n2. 现象：`std::move(x)` 之后 x 的值没变、也没变快。→ 原因：move 只是类型转换，是否移动取决于有没有移动构造。→ 正确写法：为自定义类型实现移动构造/移动赋值并标记 noexcept。\n3. 现象：返回局部对象的引用，调用方拿到悬空引用。→ 原因：局部对象离开函数即销毁。→ 正确写法：按值返回（编译器会做 RVO/移动）。\n4. 现象：用 `delete` 手动释放资源，异常路径下泄漏。→ 原因：异常跳过释放语句。→ 正确写法：用 RAII 类或 `unique_ptr` 管理资源。\n5. 现象：函数返回引用又赋值给普通变量，多了一次拷贝。→ 原因：用 `T x = f();` 而非 `T &x = f();`。→ 正确写法：需要观察时用 `const T &x = f();` 绑定。\n\n## 考点提示\n1. 引用与指针的区别（是否可为空、可否改绑、是否需解引用）。\n2. 左值/右值、右值引用与 `std::move` 的真实含义（面试高频）。\n3. RAII 与智能指针 unique_ptr / shared_ptr 的关系。\n4. 读程序写结果：引用形参与值形参混用时判断外部变量的值。\n5. `const T&` 既能绑定左值也能绑定右值，是函数形参的默认选择。',
'/code/cpp-raii',5,4,'引用,RAII,移动语义,右值引用,std::move')
